using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;
// Build-time utility: ImportSprites.exe INPUT_DIRECTORY OUTPUT_DIRECTORY.
internal static class ImportSprites {
 static int[] Cuts(int[] mass,int count,int first,int last,int radius){var cuts=new int[count+1];cuts[0]=0;cuts[count]=mass.Length;for(int k=1;k<count;k++){double expected=first+(last-first)*k/(double)count;double best=double.MaxValue;int chosen=(int)expected;for(int p=Math.Max(cuts[k-1]+8,(int)expected-radius);p<Math.Min(mass.Length-1,(int)expected+radius);p++){double score=mass[p-1]+mass[p]+mass[p+1]+Math.Abs(p-expected)*.12;if(score<best){best=score;chosen=p;}}cuts[k]=chosen;}return cuts;}
 public static void Main(string[] args){if(args.Length!=2)throw new ArgumentException("Input and output directories required");foreach(string file in Directory.GetFiles(args[0],"*.png",SearchOption.AllDirectories)){string category=new DirectoryInfo(Path.GetDirectoryName(file)).Name;if(category=="VideoJuegos")category="Videojuegos";string target=Path.Combine(args[1],category,Path.GetFileName(file));Directory.CreateDirectory(Path.GetDirectoryName(target));using(var source=new Bitmap(file)){int w=source.Width,h=source.Height;var alpha=new byte[w*h];var rows=new int[h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){byte a=source.GetPixel(x,y).A;alpha[y*w+x]=a;if(a>96)rows[y]++;}int top=0,bottom=h-1;while(top<bottom&&rows[top]<w/20)top++;while(bottom>top&&rows[bottom]<w/20)bottom--;int[] ys=Cuts(rows,4,top,bottom,55);var boxes=new Rectangle[32];int maxW=1,maxH=1;for(int row=0;row<4;row++){var cols=new int[w];for(int y=ys[row];y<ys[row+1];y++)for(int x=0;x<w;x++)if(alpha[y*w+x]>96)cols[x]++;int[] xs=Cuts(cols,8,0,w,38);for(int col=0;col<8;col++){int left=xs[col+1],right=xs[col],minY=ys[row+1],maxY=ys[row];for(int y=ys[row];y<ys[row+1];y++)for(int x=xs[col];x<xs[col+1];x++)if(alpha[y*w+x]>96){left=Math.Min(left,x);right=Math.Max(right,x);minY=Math.Min(minY,y);maxY=Math.Max(maxY,y);}if(right<left||maxY<minY)throw new Exception("Empty cell "+file+" "+col+","+row);left=Math.Max(xs[col],left-2);minY=Math.Max(ys[row],minY-2);right=Math.Min(xs[col+1]-1,right+2);maxY=Math.Min(ys[row+1]-1,maxY+2);boxes[row*8+col]=new Rectangle(left,minY,right-left+1,maxY-minY+1);maxW=Math.Max(maxW,right-left+1);maxH=Math.Max(maxH,maxY-minY+1);}}
 using(var atlas=new Bitmap(1024,512,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(atlas)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.HighQuality;float scale=Math.Min(116f/maxW,116f/maxH);for(int i=0;i<32;i++){Rectangle b=boxes[i];int dw=(int)Math.Round(b.Width*scale),dh=(int)Math.Round(b.Height*scale);g.DrawImage(source,new Rectangle(i%8*128+(128-dw)/2,i/8*128+122-dh,dw,dh),b.X,b.Y,b.Width,b.Height,GraphicsUnit.Pixel);}}atlas.Save(target,ImageFormat.Png);}
 Console.WriteLine(Path.GetFileName(file)+": 32 cells");}}}
}
